research_corpus_misconception_row(row(38076, 'Students incorrectly mix up the solution procedures for probability problems depending on whether the order of events is relevant or irrelevant.', 'Mixing up the solution procedures for ''relevant order'' and ''irrelevant order''.', 'probability', 'Combinatorics', 'Order relevance', 'other', '', 'ZDM_Renkl_2017_Learning', 'Alexander Renkl', '2017', 'ZDM Mathematics Education', 'deficit', 'primary', '578, 579', 'pdfs/ZDM/ZDM_Renkl_2017_Learning.pdf')).
