research_corpus_misconception_row(row(38078, 'Participants fail to inhibit fast, automatic thinking, leading them to give highly salient, intuitive, but incorrect answers to word problems.', 'When told a bat and a ball cost £1.10 in total and the bat costs £1 more than the ball, participants intuitively give the incorrect answer of 10 pence instead of 5 pence.', 'algebraic', 'Word problems', 'Cognitive Reflection Test', 'other', 'undergraduate students and adults', 'ZDM_Attridge_2015_Increasing', 'Nina Attridge, Matthew Inglis', '2015', 'ZDM Mathematics Education', 'uncoded', 'primary', '727, 728, 730', 'pdfs/ZDM/ZDM_Attridge_2015_Increasing.pdf')).
research_corpus_misconception_row(row(38079, 'Students'' knowledge of natural numbers interferes with operations involving rational numbers, leading to errors when comparing fractions.', 'When comparing the fractions 2/5 and 2/7, students may have an intuition that the latter is larger than the former because the natural number 7 is larger than 5.', 'rational', 'Fraction comparison', '', 'other', 'undergraduate students and adults', 'ZDM_Attridge_2015_Increasing', 'Nina Attridge, Matthew Inglis', '2015', 'ZDM Mathematics Education', 'uncoded', 'secondary', '724', 'pdfs/ZDM/ZDM_Attridge_2015_Increasing.pdf')).
research_corpus_misconception_row(row(38080, 'Students tend to erroneously apply proportional reasoning to non-proportional mathematics problems.', 'If Ellen and Kim run equally fast but Kim starts 10 laps ahead, when Ellen has run 30 laps, students incorrectly use a proportional multiplier (30 x 3 = 90) instead of additive reasoning (30 + 10 = 40).', 'proportional', 'Proportional reasoning', 'Overgeneralization', 'other', 'undergraduate students and adults', 'ZDM_Attridge_2015_Increasing', 'Nina Attridge, Matthew Inglis', '2015', 'ZDM Mathematics Education', 'uncoded', 'secondary', '724', 'pdfs/ZDM/ZDM_Attridge_2015_Increasing.pdf')).
