research_corpus_misconception_row(row(39127, 'Students commit psychologically explainable oversights lacking mathematical logic, such as suddenly adding instead of subtracting, or subtracting imaginary digits due to the persistence of a number.', '''persistence of 5'': 700 - 5 = 145, as if it were: 700 - 555', 'whole_number', 'Written subtraction', 'Algorithmic oversights', 'student', '9-12 years old', 'ESM_Fiori_2005_Experimental', 'CARLA FIORI AND LUCIANA ZUCCHERI', '2005', 'Educational Studies in Mathematics', 'deficit', 'secondary', '328', 'pdfs/ESM/ESM_Fiori_2005_Experimental.pdf')).
research_corpus_misconception_row(row(39128, 'When determining the placement of a decimal point in a multiplication product derived from a known fact, the student inappropriately matches the number of whole-number digits (digits to the left of the decimal) from the given factor to the answer, rather than counting the total number of decimal places.', 'Given 741 x 12 = 8892, to find 74.1 x 12, the student writes 88.92 because ''in seventy-four point one there was two numbers before the decimal point so I made the two numbers before the decimal point in my answer''.', 'decimal', 'Decimal multiplication', 'Decimal point placement', 'student', 'grade 6, year 7, and year 8', 'ESM_Clarke_1985_Impact', 'DAVID CLARKE', '1985', 'Educational Studies in Mathematics', 'deficit', 'primary', '240, 241', 'pdfs/ESM/ESM_Clarke_1985_Impact.pdf')).
