research_corpus_misconception_row(row(39196, 'Students apply incorrect arithmetic rules when integrating terms with negative indices, such as assuming that adding 1 to a negative exponent results in an incorrect magnitude.', 'One common error was that 1 greater than -n was taken as -(n + 1).', 'calculus', 'indefinite integration', 'negative indices', 'mixed', 'age 16-22', 'ESM_Orton_1983_Students''', 'A. ORTON', '1983', 'Educational Studies in Mathematics', 'deficit', 'secondary', '8', 'pdfs/ESM/ESM_Orton_1983_Students''.pdf')).
