research_corpus_misconception_row(row(39203, 'Students conceptualize a Riemann sum or an integral as a static total amount rather than a dynamically varying accumulation, making it difficult for them to relate the rate of change of the accumulation to the constituent quantities of the accruals.', 'When asked about the rate of change of the volume of water in a cone with respect to height, students struggled to see the area of the top disk as the rate, instead wanting to divide a small chunk of volume by a small change in height.', 'calculus', 'Fundamental Theorem of Calculus', 'Riemann sums and accumulation', 'mixed', '7th grade, senior undergraduate, and graduate', 'ESM_Thompson_1994_Images', 'PATRICK W. THOMPSON', '1994', 'Educational Studies in Mathematics', 'deficit', 'primary', '247, 251, 257, 261, 267, 268, 269', 'pdfs/ESM/ESM_Thompson_1994_Images.pdf')).
research_corpus_misconception_row(row(39204, 'Students hold a figural image of a function as a static algebraic equation rather than a covariation of two quantities, leading them to use notation opaquely and perform procedural actions without interpreting the meaning.', 'Students define a difference quotient function for falling distance but cannot explain that it represents the average speed during a tenth of a second, relying instead on ''symbol speak''.', 'calculus', 'functions', 'covariation and notation', 'mixed', '7th grade, senior undergraduate, and graduate', 'ESM_Thompson_1994_Images', 'PATRICK W. THOMPSON', '1994', 'Educational Studies in Mathematics', 'deficit', 'primary', '241, 244, 245, 268, 270', 'pdfs/ESM/ESM_Thompson_1994_Images.pdf')).
