research_corpus_misconception_row(row(39534, 'Preservice teachers incorrectly translate division word problems by applying irrelevant operations, such as dividing the smaller number into the larger or multiplying the numbers.', 'When asked how to share 5 Mars bars equally among 12 friends, a typical error was to divide the smaller number into the larger or to multiply them.', 'whole_number', 'Division', 'Word problems', 'PST', 'primary', 'MERJ_Taplin_1998_Preservice', 'Margaret Taplin', '1998', 'Mathematics Education Research Journal', 'deficit', 'primary', '64', 'pdfs/MERJ/MERJ_Taplin_1998_Preservice.pdf')).
research_corpus_misconception_row(row(39535, 'Preservice teachers erroneously apply a familiar but irrelevant formula to numbers representing ratio parts simply because a triggering keyword appears in the problem.', 'Applying the volume formula to the three numbers given for ratio parts (3 parts gravel, 2 parts sand, 1 part cement) because the problem mentioned the word volume.', 'ratio', 'Ratios and proportions', 'Word problems', 'PST', 'primary', 'MERJ_Taplin_1998_Preservice', 'Margaret Taplin', '1998', 'Mathematics Education Research Journal', 'deficit', 'secondary', '64', 'pdfs/MERJ/MERJ_Taplin_1998_Preservice.pdf')).
research_corpus_misconception_row(row(39536, 'Preservice teachers ignore critical constraints in multistep word problems, stopping after finding a single set of valid dimensions instead of optimizing for the required condition.', 'Giving only one example of possible dimensions for a 1000-liter tank and completely ignoring the request to find the dimensions that result in the smallest surface area.', 'measurement', 'Volume and surface area', 'Optimization', 'PST', 'primary', 'MERJ_Taplin_1998_Preservice', 'Margaret Taplin', '1998', 'Mathematics Education Research Journal', 'deficit', 'secondary', '64', 'pdfs/MERJ/MERJ_Taplin_1998_Preservice.pdf')).
