research_corpus_misconception_row(row(39657, 'Students incorrectly negate a conditional statement by negating both its condition and its conclusion, resulting in another conditional statement rather than a conjunction.', 'When asked to negate ''If it rains I take an umbrella'', students reply with ''If it does not rain I do not take an umbrella.''', 'discrete', 'Logic', 'Negating conditional statements', 'mixed', 'tertiary', 'MERJ_Leviatan_2008_Bridging', 'Talma Leviatan', '2008', 'Mathematics Education Research Journal', 'deficit', 'primary', '112', 'pdfs/MERJ/MERJ_Leviatan_2008_Bridging.pdf')).
