research_corpus_misconception_row(row(40319, 'Students misapply rules to compare fractions, such as claiming the fraction with the larger denominator is larger, or incorrectly adding the numerator and denominator of each fraction to compare their sums.', '18/19 is larger than 15/16 because 37 is larger than 31.', 'fraction', 'comparing fractions', 'magnitude', 'student', 'sixth grade', 'IJSME_Alsawaie_2012_Number', 'OTHMAN N. ALSAWAIE', '2012', 'International Journal of Science and Mathematics Education', 'deficit', 'primary', '1081, 1084, 1087, 1088', 'pdfs/IJSME/IJSME_Alsawaie_2012_Number.pdf')).
