research_corpus_misconception_row(row(40652, 'When determining the steepness of a ramp, a student initially focuses on the height and incorrectly considers length to be a dependent variable rather than seeing steepness as a ratio of two independently varying quantities.', 'Terry initially focused on the height of the ramp and considered its length to be a dependent variable.', 'proportional', 'steepness', 'slope', 'other', '', 'MTL_Selden_2005_Perspectives', 'Annie Selden, John Selden', '2005', 'Mathematical Thinking and Learning', 'mixed', 'secondary', '8', 'pdfs/MTL/MTL_Selden_2005_Perspectives.pdf')).
